#!/usr/bin/env perl
# gen_errors.pl - generates the per-language error dictionaries from
# common/error_codes.txt (single source of truth). Core modules only.
#
#   gen_errors.pl           write the generated files (only when content changed)
#   gen_errors.pl --check   exit 1 if any generated file is missing or stale
use v5.40;

use Cwd            qw(abs_path);
use File::Basename qw(dirname);
use File::Path     qw(make_path);
use File::Spec;
use FindBin      qw($RealBin);
use Getopt::Long qw(GetOptions);

my $check_only = 0;
GetOptions( 'check' => \$check_only ) or die "usage: gen_errors.pl [--check]\n";

my $ROOT   = abs_path( File::Spec->catdir( $RealBin, File::Spec->updir ) );
my $SOURCE = "$ROOT/common/error_codes.txt";

my %TARGETS = (
    "$ROOT/common/include/ffi_bridge/error_codes.h" => \&render_c_header,
    "$ROOT/rust/src/error_codes.rs"                 => \&render_rust,
    "$ROOT/cpp/include/ffi_bridge/error_table.hpp"  => \&render_cpp_table,
);

sub parse_source($path) {
    open( my $fh, '<', $path ) or die "cannot open $path: $!\n";
    my ( @entries, %seen_code, %seen_name );
    while ( my $line = <$fh> ) {
        chomp $line;
        next if $line =~ /^\s*(?:#|$)/;
        my ( $code, $name, $message ) = split /\|/, $line, 3;
        die "$path:$.: expected CODE|NAME|MESSAGE\n" unless defined $message;
        s/^\s+|\s+$//g for ( $code, $name, $message );
        die "$path:$.: invalid code '$code'\n" unless $code =~ /^[0-9]{1,9}$/;
        die "$path:$.: invalid name '$name'\n"
          unless $name =~ /^[A-Z][A-Z0-9_]*$/;
        die "$path:$.: message must be printable ASCII\n"
          unless $message =~ /^[\x20-\x7E]+$/;
        die "$path:$.: duplicate code $code\n" if $seen_code{$code}++;
        die "$path:$.: duplicate name $name\n" if $seen_name{$name}++;
        push @entries,
          { code => $code + 0, name => $name, message => $message };
    }
    close $fh;
    for my $required (qw(OK UNKNOWN_CODE)) {
        die "$path: required entry '$required' is missing\n"
          unless $seen_name{$required};
    }
    return \@entries;
}

sub escape_string($text) {
    $text =~ s/(["\\])/\\$1/g;
    return $text;
}

sub render_c_header($entries) {
    my $enum = join( ",\n",
        map { sprintf '    FFI_%s = %d', $_->{name}, $_->{code} } @$entries );
    my $count = scalar @$entries;
    return <<~"EOT";
    /* GENERATED by scripts/gen_errors.pl from common/error_codes.txt. DO NOT EDIT. */
    #ifndef FFI_BRIDGE_ERROR_CODES_H
    #define FFI_BRIDGE_ERROR_CODES_H

    enum ffi_error_code {
    $enum
    };

    #define FFI_ERROR_COUNT $count

    #endif /* FFI_BRIDGE_ERROR_CODES_H */
    EOT
}

sub render_rust($entries) {
    my $consts = join( "\n",
        map { sprintf 'pub const %s: i32 = %d;', $_->{name}, $_->{code} }
          @$entries );
    my $rows = join(
        "\n",
        map {
            sprintf '    (%d, "%s"),', $_->{code},
              escape_string( $_->{message} )
        } @$entries
    );
    return <<~"EOT";
    // GENERATED by scripts/gen_errors.pl from common/error_codes.txt. DO NOT EDIT.

    $consts

    /// Every (code, message) pair; used to build the HashMap dictionary.
    pub const ENTRIES: &[(i32, &str)] = &[
    $rows
    ];
    EOT
}

sub render_cpp_table($entries) {
    my $count = scalar @$entries;
    my $rows  = join(
        "\n",
        map {
            sprintf '    {%d, "%s"},', $_->{code},
              escape_string( $_->{message} )
        } @$entries
    );
    return <<~"EOT";
    // GENERATED by scripts/gen_errors.pl from common/error_codes.txt. DO NOT EDIT.
    #pragma once

    #include <array>
    #include <cstdint>
    #include <string_view>
    #include <utility>

    namespace ffi_bridge::generated {

    inline constexpr std::array<std::pair<std::int32_t, std::string_view>, $count> kErrorEntries{{
    $rows
    }};

    }  // namespace ffi_bridge::generated
    EOT
}

sub slurp($path) {
    open( my $fh, '<', $path ) or die "cannot read $path: $!\n";
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content;
}

sub spew( $path, $content ) {
    make_path( dirname($path) );
    open( my $fh, '>', $path ) or die "cannot write $path: $!\n";
    print {$fh} $content;
    close $fh or die "cannot close $path: $!\n";
    return;
}

my $entries = parse_source($SOURCE);
my $stale   = 0;

for my $path ( sort keys %TARGETS ) {
    my $content  = $TARGETS{$path}->($entries);
    my $existing = -e $path ? slurp($path) : undef;
    my $current  = defined $existing && $existing eq $content;
    my $rel      = File::Spec->abs2rel( $path, $ROOT );

    if ($check_only) {
        unless ($current) {
            say STDERR "stale or missing: $rel";
            $stale++;
        }
        next;
    }
    next if $current;    # keep mtime untouched to avoid needless rebuilds
    spew( $path, $content );
    say "generated $rel";
}

exit( $stale ? 1 : 0 );
